def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_op = history[-1]

    if last_op == 'C':
        return 'C'
    else:
        if last_me == 'C':
            if n >= 2 and history[-2][1] == 'D':
                return 'D'
            return 'C'
        else:
            if n >= 2 and history[-2][1] == 'D':
                return 'D'
            return 'C'
